begin;
set local search_path=public,extensions;
select plan(32);
revoke all on auth.users from service_role;
select ok(not has_function_privilege('anon','public.queue_payment_request_email(uuid,boolean,text)','EXECUTE'),'public visitors cannot send payment requests');
select ok(not has_table_privilege('authenticated','app_private.customer_event_emails','SELECT'),'customer event queue is private');
select ok(not has_function_privilege('authenticated','public.account_email_context(uuid,integer)','EXECUTE'),'account email summaries are worker-only');
insert into auth.users(id,email,created_at,updated_at,email_confirmed_at,raw_user_meta_data) values
('a1000000-0000-4000-8000-000000000001','lifecycle-owner@example.test',now(),now(),now(),'{"workloop_email_notice":"workloop-account-emails-2026-09-v1","workloop_email_updates":true}');

-- Authenticated fixtures use real sessions, as production access requires.
insert into auth.sessions(id,user_id,created_at,updated_at) values
('a1000000-0000-4000-8000-000000000101','a1000000-0000-4000-8000-000000000001',now(),now());
select is((public.account_email_context((select id from app_private.learning_contacts where email='lifecycle-owner@example.test'),10)->>'setup_step'),'finish_workspace','missing workspace gets specific help');
insert into public.workspaces(id,name) values('a2000000-0000-4000-8000-000000000001','Lifecycle test');
insert into public.workspace_members(workspace_id,user_id) values('a2000000-0000-4000-8000-000000000001','a1000000-0000-4000-8000-000000000001');
insert into public.workspace_settings(workspace_id,timezone) values('a2000000-0000-4000-8000-000000000001','Europe/London') on conflict(workspace_id) do update set timezone=excluded.timezone;
select is((public.account_email_context((select id from app_private.learning_contacts where email='lifecycle-owner@example.test'),10)->>'setup_step'),'add_service','service help only when needed');
insert into public.services(id,workspace_id,name,duration_mins,price) values('a3000000-0000-4000-8000-000000000001','a2000000-0000-4000-8000-000000000001','Clean',60,45);
select is((public.account_email_context((select id from app_private.learning_contacts where email='lifecycle-owner@example.test'),10)->>'setup_step'),'add_client','next help moves to client');
insert into public.contacts(id,workspace_id,name,email) values('a4000000-0000-4000-8000-000000000001','a2000000-0000-4000-8000-000000000001','Sample customer','lifecycle-customer@example.test');
select is((public.account_email_context((select id from app_private.learning_contacts where email='lifecycle-owner@example.test'),12)->>'setup_step'),'add_booking','next help moves to booking');
insert into public.booking_requests(id,workspace_id,name,phone,email,service_id,requested_for,status) values('a5000000-0000-4000-8000-000000000001','a2000000-0000-4000-8000-000000000001','Sample customer','07123456789','lifecycle-customer@example.test','a3000000-0000-4000-8000-000000000001',now()+interval '2 days','pending');
select is((select count(*)::integer from app_private.customer_event_emails where event='request_received'),1,'new request gets acknowledgement');
update public.booking_requests set status='declined' where id='a5000000-0000-4000-8000-000000000001';
select is((select status from app_private.customer_event_emails where event='request_received'),'cancelled','decline cancels obsolete acknowledgement');
select is((select count(*)::integer from app_private.customer_event_emails where event='request_declined'),1,'decline gets one email');
update public.booking_requests set status='declined' where id='a5000000-0000-4000-8000-000000000001';
select is((select count(*)::integer from app_private.customer_event_emails where event='request_declined'),1,'no duplicate on unchanged status');
insert into public.appointments(id,workspace_id,contact_id,service_id,title,start_time,end_time,price,status) values('a6000000-0000-4000-8000-000000000001','a2000000-0000-4000-8000-000000000001','a4000000-0000-4000-8000-000000000001','a3000000-0000-4000-8000-000000000001','Clean',now()+interval '2 days',now()+interval '2 days 1 hour',45,'scheduled');
select ok((public.account_email_context((select id from app_private.learning_contacts where email='lifecycle-owner@example.test'),10)->>'setup_step') is null,'finished setup does not get setup prompt');
update public.appointments set notes='NEVER EMAIL PRIVATE NOTES' where id='a6000000-0000-4000-8000-000000000001';
select is((select count(*)::integer from app_private.customer_event_emails where event='booking_changed'),0,'private-note edit does not notify customer');
update public.appointments set start_time=start_time+interval '1 hour',end_time=end_time+interval '1 hour' where id='a6000000-0000-4000-8000-000000000001';
select is((select count(*)::integer from app_private.customer_event_emails where event='booking_changed'),1,'reschedule queues updated details');
select ok(not exists(select 1 from app_private.customer_event_emails where payload::text like '%NEVER EMAIL%'),'private notes excluded from payload');
create temp table leased as select * from public.claim_customer_event_emails(5);
update public.appointments set status='cancelled' where id='a6000000-0000-4000-8000-000000000001';
select ok(not (select public.customer_event_still_allowed(id,lease_token) from leased where event='booking_changed'),'cancellation revokes leased reschedule email');
select is((select count(*)::integer from app_private.customer_event_emails where event='booking_cancelled'),1,'cancellation is captured');
insert into public.invoices(id,workspace_id,contact_id,appointment_id,invoice_number,issue_date,total,amount_paid,status) values('a7000000-0000-4000-8000-000000000001','a2000000-0000-4000-8000-000000000001','a4000000-0000-4000-8000-000000000001','a6000000-0000-4000-8000-000000000001','PAY-LIFECYCLE',current_date,45,0,'sent');
insert into public.payment_transactions(id,workspace_id,invoice_id,stripe_account_id,stripe_checkout_session_id,collection_method,status,amount_minor,idempotency_key,metadata) values('a8000000-0000-4000-8000-000000000001','a2000000-0000-4000-8000-000000000001','a7000000-0000-4000-8000-000000000001','acct_Test','cs_Test','payment_link','pending',4500,'lifecycle-test-payment-01','{"checkout_url":"https://checkout.stripe.com/c/pay/example"}');
select set_config('request.jwt.claim.sub','a1000000-0000-4000-8000-000000000001',true);
select set_config('request.jwt.claims','{"sub":"a1000000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal1","session_id":"a1000000-0000-4000-8000-000000000101"}',true);
set local role authenticated;
select is(public.queue_payment_request_email('a8000000-0000-4000-8000-000000000001',false)->>'email','lifecycle-customer@example.test','payment review resolves actual saved recipient');
select throws_ok($$select public.queue_payment_request_email('a8000000-0000-4000-8000-000000000001',true,'changed@example.test')$$,'P0001','Customer email changed. Review the recipient again','stale review cannot send to changed address');
select lives_ok($$select public.queue_payment_request_email('a8000000-0000-4000-8000-000000000001',true,'lifecycle-customer@example.test')$$,'owner deliberately queues request');
select public.queue_payment_request_email('a8000000-0000-4000-8000-000000000001',true,'lifecycle-customer@example.test');
reset role;
select is((select count(*)::integer from app_private.customer_event_emails where event='payment_request'),1,'double tap does not duplicate payment request');
update public.contacts set email='changed@example.test' where id='a4000000-0000-4000-8000-000000000001';
set local role authenticated;
select throws_ok($$select public.queue_payment_request_email('a8000000-0000-4000-8000-000000000001',true,'changed@example.test')$$,'P0001','Customer email changed. Create a fresh payment link','queued recipient cannot silently change');
select throws_ok($$select public.queue_payment_request_email('ffffffff-0000-4000-8000-000000000001',false)$$,'P0001','Payment access denied','unknown transaction denied');
reset role;
update public.contacts set email='lifecycle-customer@example.test' where id='a4000000-0000-4000-8000-000000000001';
update public.payment_transactions set amount_minor=2000 where id='a8000000-0000-4000-8000-000000000001';
set local role authenticated;
select lives_ok($$select public.queue_payment_request_email('a8000000-0000-4000-8000-000000000001',false)$$,'partial collection can be previewed');
reset role;
-- Provider transaction amount changes must invalidate already composed amounts.
select ok(not app_private.customer_event_allowed((select id from app_private.customer_event_emails where event='payment_request')),'changed transaction amount revokes stale request');
update public.payment_transactions set amount_minor=4500 where id='a8000000-0000-4000-8000-000000000001';
select set_config('request.jwt.claim.sub','ffffffff-0000-4000-8000-000000000001',true);
select set_config('request.jwt.claims','{"sub":"ffffffff-0000-4000-8000-000000000001","role":"authenticated","aal":"aal1"}',true);
set local role authenticated;
select throws_ok($$select public.queue_payment_request_email('a8000000-0000-4000-8000-000000000001',false)$$,'P0001','Payment access denied','another workspace user cannot request payment');
reset role;
select set_config('request.jwt.claim.sub','a1000000-0000-4000-8000-000000000001',true);
select set_config('request.jwt.claims','{"sub":"a1000000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal1","session_id":"a1000000-0000-4000-8000-000000000101"}',true);
update public.payment_transactions set status='succeeded' where id='a8000000-0000-4000-8000-000000000001';
select ok(not app_private.customer_event_allowed((select id from app_private.customer_event_emails where event='payment_request')),'paid transaction prevents pending payment email');
set local role service_role;
select lives_ok($$select public.claim_customer_event_emails(5)$$,'service worker works without direct Auth access');
select lives_ok($$select public.account_email_context((select id from app_private.learning_contacts where email='lifecycle-owner@example.test'),1005)$$,'weekly summary works with real hosted Auth permissions');
reset role;
select is((public.account_email_context((select id from app_private.learning_contacts where email='lifecycle-owner@example.test'),1005)#>>'{summary,upcoming_bookings}')::integer,0,'cancelled booking is excluded from upcoming count');
update app_private.learning_contacts set status='unsubscribed' where email='lifecycle-owner@example.test';
select is(public.account_email_context((select id from app_private.learning_contacts where email='lifecycle-owner@example.test'),1005),'{}'::jsonb,'unsubscribed account has no email summary');
delete from public.workspaces where id='a2000000-0000-4000-8000-000000000001';
select is((select count(*)::integer from app_private.customer_event_emails),0,'workspace deletion removes queued email data');
select * from finish();
rollback;
